-- Passage rg4-argument-evidence-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('dc3c8e03-86f7-55f4-88a7-c523f0066106', 'rg4-argument-evidence-p02', (select id from public.skills where slug = 'read-g4-argument-evidence'), null,
        '3-5', $q$Every Child Should Learn to Swim$q$, $q$Swimming is more than a fun summer activity. It is a skill that helps people stay safe and healthy. Every child should have the chance to take swimming lessons.

Swimming keeps children safe near water. Many families spend time at lakes, pools and beaches. A child who knows how to float and swim to the edge is much safer there. Lifeguards teach that strong swimmers know what to do if they get tired in the water.

Swimming is also great exercise. It works the arms, the legs and the heart all at once. Because water holds up the body, swimming is gentle on the knees and other joints. People can keep swimming even when they are very old.

Finally, swimming opens the door to other activities. Children who can swim can try sailing, snorkeling and water polo. At Bayview Day Camp, only campers who pass a swim test may go canoeing.

Some people say lessons are too expensive. However, many town pools offer free or low-cost classes in the summer. The Riverside town pool taught 200 children to swim for free last July.

Learning to swim is a gift that lasts a lifetime.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
